mapper.select:
SELECT a.activity_id AS activityId, a.title, c.name AS clubName, a.time, a.location, a.status, (SELECT COUNT(*) FROM activity_signup WHERE activity_id = a.activity_id) AS signupCount, CASE a.status WHEN '1' THEN '待确定' WHEN '2' THEN '已通过' WHEN '3' THEN '进行中' WHEN '4' THEN '已结束' WHEN '5' THEN '已拒绝' ELSE '' END AS statusText FROM activity a LEFT JOIN club c ON a.club_id = c.club_id WHERE 1 = 1
AND a.status = #{queryDto.status}
AND c.name LIKE CONCAT('%', #{queryDto.clubName}, '%')
AND a.time >= #{queryDto.startTime}
AND a.time <= #{queryDto.endTime}
ORDER BY a.created_at DESC LIMIT #{queryDto.pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM activity a
LEFT JOIN club c ON a.club_id = c.club_id
WHERE 1 = 1

    AND a.status = #{queryDto.status}


    AND c.name LIKE CONCAT('%', #{queryDto.clubName}, '%')


    AND a.time >= #{queryDto.startTime}


    AND a.time <= #{queryDto.endTime}
